import { isBetterPaymentPaidStatus } from "@/src/better-payment/shared";

export const runtime = "nodejs";

/**
 * Better Payment Postback (Webhook).
 * Acknowledges notification; MCP has no Zahlungslink store — use get_payment_link_status to poll.
 */
async function parseBody(request: Request): Promise<Record<string, unknown>> {
  let bodyText = "";
  try {
    bodyText = await request.text();
  } catch {
    bodyText = "";
  }

  try {
    return bodyText ? (JSON.parse(bodyText) as Record<string, unknown>) : {};
  } catch {
    try {
      const params = new URLSearchParams(bodyText);
      const payload: Record<string, unknown> = {};
      for (const [k, v] of params.entries()) payload[k] = v;
      return payload;
    } catch {
      return {};
    }
  }
}

export async function POST(request: Request) {
  const payload = await parseBody(request);

  const orderId =
    (typeof payload.order_id === "string" && payload.order_id) ||
    (typeof payload.merchant_reference === "string" &&
      payload.merchant_reference) ||
    null;
  const transactionId =
    typeof payload.transaction_id === "string" ? payload.transaction_id : null;
  const status = typeof payload.status === "string" ? payload.status : null;
  const statusCodeRaw = payload.status_code;
  const statusCode =
    typeof statusCodeRaw === "number"
      ? statusCodeRaw
      : typeof statusCodeRaw === "string" && /^\d+$/.test(statusCodeRaw)
        ? Number(statusCodeRaw)
        : null;

  console.info("[better-payment/postback]", {
    orderId,
    transactionId,
    status,
    statusCode,
    paid: isBetterPaymentPaidStatus(status, statusCode),
    signature: request.headers.get("gateway-webhook-signature"),
  });

  return Response.json(
    {
      ok: true,
      received: true,
      orderId,
      transactionId,
      status,
      statusCode,
      paid: isBetterPaymentPaidStatus(status, statusCode),
    },
    { status: 200 }
  );
}

export async function GET() {
  return Response.json({
    ok: true,
    service: "better-payment-postback",
  });
}

export const runtime = "nodejs";

/**
 * Browser return landing after Wero / Pay by Bank redirect.
 * Better Payment requires https success/error URLs; this is a minimal ack page.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const result = url.searchParams.get("result") ?? "unknown";
  const orderId = url.searchParams.get("order_id");
  const method = url.searchParams.get("method");

  const title =
    result === "success"
      ? "Zahlung abgeschlossen"
      : result === "error"
        ? "Zahlung fehlgeschlagen"
        : "Zahlung";

  const html = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${title}</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 32rem; margin: 3rem auto; padding: 0 1rem; color: #111; }
    h1 { font-size: 1.35rem; }
    p { color: #444; line-height: 1.5; }
    code { background: #f3f3f3; padding: 0.1rem 0.35rem; border-radius: 4px; }
  </style>
</head>
<body>
  <h1>${title}</h1>
  <p>Methode: <code>${method ?? "—"}</code></p>
  <p>Order-ID: <code>${orderId ?? "—"}</code></p>
  <p>Sie können dieses Fenster schließen. Der Status kann über das MCP-Tool <code>get_payment_link_status</code> abgefragt werden.</p>
</body>
</html>`;

  return new Response(html, {
    status: 200,
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

