import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  serverExternalPackages: [
    "@modelcontextprotocol/sdk",
    "mcp-handler",
    "@azure/identity",
    "@azure/keyvault-certificates",
    "@azure/keyvault-keys",
    "node-forge",
  ],
