    config.resolve = config.resolve ?? {};
    config.resolve.extensionAlias = {
      ".js": [".ts", ".tsx", ".js"],
    };
    return config;
  },
};

export default nextConfig;

import { createHash } from "node:crypto";
import { CertificateClient } from "@azure/keyvault-certificates";
import { CryptographyClient } from "@azure/keyvault-keys";
import { DefaultAzureCredential, ClientSecretCredential } from "@azure/identity";

function env(key: string): string {
  return (process.env[key] ?? "").trim();
}

export type AzureKeyVaultConfig = {
  vaultUrl: string;
};

export function isAzureKeyVaultConfigured(): boolean {
  return Boolean(env("AZURE_KEY_VAULT_URL"));
}

export function resolveAzureKeyVaultConfig(): AzureKeyVaultConfig | null {
  const vaultUrl = env("AZURE_KEY_VAULT_URL");
  if (!vaultUrl) return null;
  return { vaultUrl };
}

export function getAzureCredential() {
  const tenantId = env("AZURE_TENANT_ID");
  const clientId = env("AZURE_CLIENT_ID");
  const clientSecret = env("AZURE_CLIENT_SECRET");
  if (tenantId && clientId && clientSecret) {
    return new ClientSecretCredential(tenantId, clientId, clientSecret);
  }
  return new DefaultAzureCredential();
}

export async function keyVaultResolveKeyId(
  certificateName: string,
  _teamId?: string
): Promise<string> {
  const config = resolveAzureKeyVaultConfig();
  if (!config?.vaultUrl) {
    throw new Error("Azure Key Vault ist nicht konfiguriert (AZURE_KEY_VAULT_URL).");
  }
  const name = certificateName.trim();
  if (!name) throw new Error("Zertifikatsname fehlt.");

  const certClient = new CertificateClient(config.vaultUrl, getAzureCredential());
  const cert = await certClient.getCertificate(name);
  if (!cert.keyId) {
    throw new Error("Schlüssel-ID nicht gefunden — Zertifikat evtl. noch nicht gemerged.");
  }
  return cert.keyId;
}

export async function keyVaultSignCbConnectPayload(
  keyId: string,
  signingInput: string,
  _teamId?: string
): Promise<string> {
  if (!isAzureKeyVaultConfigured()) {
    throw new Error("Azure Key Vault ist nicht konfiguriert.");
  }
  const digest = createHash("sha256").update(signingInput, "utf8").digest();
  const crypto = new CryptographyClient(keyId, getAzureCredential());
  const result = await crypto.sign("RS256", digest);
  return Buffer.from(result.result).toString("base64");
}

export async function keyVaultSignCbConnectPayloadForCertificate(
  certificateName: string,
  signingInput: string,
  teamId?: string
): Promise<{ signatureBase64: string; keyId: string }> {
  const keyId = await keyVaultResolveKeyId(certificateName, teamId);
  const signatureBase64 = await keyVaultSignCbConnectPayload(
    keyId,
    signingInput,
    teamId
  );
  return { signatureBase64, keyId };
}

import type { BetterPaymentMethodId } from "./shared.js";

export type BetterPaymentCredentials = {
  apiKey: string;
  outgoingKey: string;
  apiBaseUrl: string;
};

export class BetterPaymentApiError extends Error {
  status: number;
  bodyText: string;

  constructor(message: string, status: number, bodyText: string) {
    super(message);
    this.name = "BetterPaymentApiError";
    this.status = status;
    this.bodyText = bodyText;
  }
}

function basicAuthHeader(apiKey: string, outgoingKey: string): string {
  const token = Buffer.from(`${apiKey}:${outgoingKey}`, "utf8").toString(
    "base64"
  );
  return `Basic ${token}`;
}

function joinUrl(base: string, path: string): string {
  const b = base.replace(/\/+$/, "");
  const p = path.startsWith("/") ? path : `/${path}`;
  return `${b}${p}`;
}

export async function betterPaymentFetch(
  creds: BetterPaymentCredentials,
  path: string,
  init?: RequestInit
): Promise<Response> {
  const url = joinUrl(creds.apiBaseUrl, path);
  const headers = new Headers(init?.headers);
  headers.set(
    "Authorization",
    basicAuthHeader(creds.apiKey, creds.outgoingKey)
  );
  if (!headers.has("Accept")) {
    headers.set("Accept", "application/json");
  }
  if (init?.body && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }

  return fetch(url, {
    ...init,
    headers,
    cache: "no-store",
  });
}

export async function betterPaymentFetchJson<T = unknown>(
  creds: BetterPaymentCredentials,
  path: string,
  init?: RequestInit
): Promise<{ status: number; data: T; raw: string }> {
  const res = await betterPaymentFetch(creds, path, init);
  const raw = await res.text();
  let data: T;
  try {
    data = (raw ? JSON.parse(raw) : null) as T;
  } catch {
    throw new BetterPaymentApiError(
      `Better Payment antwortete nicht mit JSON (HTTP ${res.status}).`,
      res.status,
      raw.slice(0, 4000)
    );
  }
  if (!res.ok) {
    const msg = extractBetterPaymentErrorMessage(data, res.status);
    throw new BetterPaymentApiError(msg, res.status, raw.slice(0, 8000));
  }
  return { status: res.status, data, raw };
}

function extractBetterPaymentErrorMessage(data: unknown, status: number): string {
  if (data && typeof data === "object") {
    const o = data as Record<string, unknown>;
    if (typeof o.error_message === "string" && o.error_message.trim()) {
      const code =
        typeof o.error_code === "number" || typeof o.error_code === "string"
          ? ` (error_code ${o.error_code})`
          : "";
      return `${o.error_message.trim()}${code}`;
    }
    if (typeof o.message === "string" && o.message.trim()) {
      return o.message.trim();
    }
  }
  return `Better Payment HTTP ${status}`;
}

/** Auth-Smoke-Test: Transaktionsliste abrufen (BASIC AUTH). */
export async function betterPaymentProbeAuth(
  creds: BetterPaymentCredentials
): Promise<{ status: number; data: unknown; raw: string }> {
  return betterPaymentFetchJson(creds, "/rest/transactions?per=1");
}

export type BetterPaymentCreatePaymentInput = {
  paymentType: BetterPaymentMethodId;
  amount: number;
  currency: string;
  orderId: string;
  merchantReference?: string;
  successUrl: string;
  errorUrl: string;
  /** Required for Wero */
  weroCheckoutUrl?: string;
  postbackUrl?: string;
  billing: {
    firstName: string;
    lastName: string;
    email?: string;
    address: string;
    city: string;
    postalCode: string;
    country: string;
  };
};

export type BetterPaymentCreatePaymentResponse = {
  transaction_id?: string;
  order_id?: string;
  status_code?: number;
  status?: string;
  error_code?: number;
  error_message?: string;
  message?: string;
  client_action?: string;
  action_data?: {
    url?: string;
    fields?: Record<string, string>;
  };
  [key: string]: unknown;
};

export type BetterPaymentTransaction = {
  transaction_id?: string;
  order_id?: string;
  status_code?: number;
  status?: string;
  amount?: number;
  currency?: string;
  payment_type?: string;
  merchant_reference?: string;
  error_code?: number;
  error_message?: string;
  [key: string]: unknown;
};

export async function betterPaymentCreatePayment(
  creds: BetterPaymentCredentials,
  input: BetterPaymentCreatePaymentInput
): Promise<{
  status: number;
  data: BetterPaymentCreatePaymentResponse;
  raw: string;
  requestBody: Record<string, unknown>;
}> {
  const requestBody: Record<string, unknown> = {
    payment_type: input.paymentType,
    amount: input.amount,
    currency: input.currency,
    order_id: input.orderId,
    merchant_reference: input.merchantReference ?? input.orderId,
    success_url: input.successUrl,
    error_url: input.errorUrl,
    first_name: input.billing.firstName,
    last_name: input.billing.lastName,
    address: input.billing.address,
    city: input.billing.city,
    postal_code: input.billing.postalCode,
    country: input.billing.country,
  };

  if (input.billing.email) {
    requestBody.email = input.billing.email;
  }
  // postback_url ist laut API Pflicht und muss https nutzen.
  if (!input.postbackUrl?.trim()) {
    throw new BetterPaymentApiError(
      "postback_url (HTTPS) ist Pflicht für Better Payment.",
      400,
      ""
    );
  }
  requestBody.postback_url = input.postbackUrl.trim();
  if (input.paymentType === "wero") {
    requestBody.wero_checkout_url =
      input.weroCheckoutUrl?.trim() || input.successUrl;
  }

  const result = await betterPaymentFetchJson<BetterPaymentCreatePaymentResponse>(
    creds,
    "/rest/payment",
    {
      method: "POST",
      body: JSON.stringify(requestBody),
    }
  );

  const errorCode = result.data?.error_code;
  if (typeof errorCode === "number" && errorCode !== 0) {
    const msg =
      typeof result.data.error_message === "string" &&
      result.data.error_message.trim()
        ? result.data.error_message.trim()
        : typeof result.data.message === "string" && result.data.message.trim()
          ? result.data.message.trim()
          : `Better Payment error_code ${errorCode}`;
    throw new BetterPaymentApiError(
      `${msg} (error_code ${errorCode})`,
      result.status,
      result.raw.slice(0, 8000)
    );
  }

  return {
    ...result,
    requestBody,
  };
}

export async function betterPaymentGetTransaction(
  creds: BetterPaymentCredentials,
  transactionId: string
): Promise<BetterPaymentTransaction> {
  const id = transactionId.trim();
  if (!id) throw new Error("transactionId fehlt.");
  const { data } = await betterPaymentFetchJson<BetterPaymentTransaction>(
    creds,
    `/rest/transactions/${encodeURIComponent(id)}`
  );
  return data;
}

export async function betterPaymentFindTransactionsByOrderId(
  creds: BetterPaymentCredentials,
  orderId: string
): Promise<BetterPaymentTransaction[]> {
  const oid = orderId.trim();
  if (!oid) throw new Error("orderId fehlt.");
  const q = new URLSearchParams({ order_id: oid });
  const { data } = await betterPaymentFetchJson<unknown>(
    creds,
    `/rest/transactions?${q.toString()}`
  );
  if (Array.isArray(data)) {
    return data as BetterPaymentTransaction[];
  }
  if (data && typeof data === "object") {
    const o = data as Record<string, unknown>;
    if (Array.isArray(o.transactions)) {
      return o.transactions as BetterPaymentTransaction[];
    }
    if (Array.isArray(o.data)) {
      return o.data as BetterPaymentTransaction[];
    }
    // single object response
    if (typeof o.transaction_id === "string" || typeof o.order_id === "string") {
      return [o as BetterPaymentTransaction];
    }
  }
  return [];
}

/**
 * Better Payment — credentials from server env (no team store).
 */

import {
  betterPaymentBaseUrlForEnvironment,
  type BetterPaymentEnvironment,
} from "./shared.js";

export type BetterPaymentEnvCredentials = {
  apiKey: string;
  outgoingKey: string;
  incomingKey: string;
  environment: BetterPaymentEnvironment;
  apiBaseUrl: string;
  publicOrigin: string | null;
};

function env(key: string): string {
  const direct = (process.env[key] ?? "").trim();
  if (direct) return direct;
  for (const [k, v] of Object.entries(process.env)) {
    if (k.trim() === key && typeof v === "string") return v.trim();
  }
  return "";
}

export function readBetterPaymentEnvironment(): BetterPaymentEnvironment {
  const raw = env("BETTER_PAYMENT_ENVIRONMENT").toLowerCase();
  return raw === "live" ? "live" : "sandbox";
}

/**
 * Öffentliche HTTPS-Origin für success/error/postback/wero_checkout_url.
 * Better Payment lehnt http:// ab (error_code 149).
 */
export function readBetterPaymentPublicOrigin(): string | null {
  const candidates = [
    env("BETTER_PAYMENT_PUBLIC_ORIGIN"),
    process.env.NEXT_PUBLIC_APP_URL?.trim() ?? "",
    process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : "",
  ].filter(Boolean);

  for (const raw of candidates) {
    try {
      const url = new URL(raw.startsWith("http") ? raw : `https://${raw}`);
      if (url.protocol === "https:") return url.origin;
    } catch {
      /* ignore */
    }
  }
  return null;
}

/** Erzwingt https:// — für Sandbox-Tests ohne Tunnel (localhost → https://localhost). */
export function ensureHttpsOrigin(origin: string): string {
  try {
    const url = new URL(origin);
    url.protocol = "https:";
    return url.origin;
  } catch {
    return "https://localhost";
  }
}

export function readBetterPaymentEnv(): BetterPaymentEnvCredentials {
  const environment = readBetterPaymentEnvironment();
  const override = env("BETTER_PAYMENT_API_BASE");
  return {
    apiKey: env("BETTER_PAYMENT_API_KEY"),
    outgoingKey: env("BETTER_PAYMENT_OUTGOING_KEY"),
    incomingKey: env("BETTER_PAYMENT_INCOMING_KEY"),
    environment,
    apiBaseUrl: override || betterPaymentBaseUrlForEnvironment(environment),
    publicOrigin: readBetterPaymentPublicOrigin(),
  };
}

export function hasBetterPaymentEnv(): boolean {
  const e = readBetterPaymentEnv();
  return Boolean(e.apiKey || e.outgoingKey || e.incomingKey);
}

import { readBetterPaymentEnv } from "./env-config.js";

export type BetterPaymentResolvedCredentials = {
  apiKey: string;
  outgoingKey: string;
  incomingKey: string;
  apiBaseUrl: string;
  publicOrigin: string | null;
  environment: "sandbox" | "live";
};

export function betterPaymentGetResolvedCredentials(): BetterPaymentResolvedCredentials {
  const e = readBetterPaymentEnv();
  return {
    apiKey: e.apiKey,
    outgoingKey: e.outgoingKey,
    incomingKey: e.incomingKey,
    apiBaseUrl: e.apiBaseUrl,
    publicOrigin: e.publicOrigin,
    environment: e.environment,
  };
}

export function validateBetterPaymentCredentials(
  creds: BetterPaymentResolvedCredentials
): string | null {
  if (!creds.apiKey) return "BETTER_PAYMENT_API_KEY fehlt.";
  if (!creds.outgoingKey) return "BETTER_PAYMENT_OUTGOING_KEY fehlt.";
  if (!creds.apiBaseUrl) return "Better Payment API-Base-URL fehlt.";
  return null;
}

/**
 * Better Payment (Deutsche Bank) — Payment Gateway.
 * Docs: https://testdashboard.betterpayment.de/docs
 *
 * Methods: Wero (`wero`) and Pay by Bank / RTP (`rtp`).
 */

export type BetterPaymentEnvironment = "sandbox" | "live";

/** API payment_type codes. */
export type BetterPaymentMethodId = "wero" | "rtp";

/** Friendly aliases accepted by MCP tools. */
export type BetterPaymentMethodAlias =
  | BetterPaymentMethodId
  | "pay_by_bank"
  | "pay-by-bank"
  | "vero"; // common misspelling of Wero

export type BetterPaymentMethodMeta = {
  id: BetterPaymentMethodId;
  paymentType: BetterPaymentMethodId;
  title: string;
  description: string;
  aliases: BetterPaymentMethodAlias[];
};

export const BETTER_PAYMENT_METHODS: BetterPaymentMethodMeta[] = [
  {
    id: "wero",
    paymentType: "wero",
    title: "Wero",
    description:
      "Mobile Zahlung der Deutschen Bank — Redirect zur QR-Code-Seite, Bestätigung in der Wero-App.",
    aliases: ["wero", "vero"],
  },
  {
    id: "rtp",
    paymentType: "rtp",
