): Promise<{
  status: number;
  body: string;
  correlationId: string;
  requestHeaders?: Record<string, string>;
}> {
  const extraHeaders = bankingRequestHeaders(
    creds,
    headerParams.correlationId,
    {
      branchIdentifier: headerParams.branchIdentifier.trim(),
      accountIdentifier: headerParams.accountIdentifier.trim(),
      clientBIC: headerParams.clientBic.trim(),
    }
  );

  if (options?.allowErrorStatus) {
    const res = await cbConnectSignedPostResult(
      creds,
      url,
      accessToken,
      body,
      extraHeaders
    );
    return { ...res, correlationId: headerParams.correlationId };
  }

  const res = await cbConnectSignedPost(creds, url, accessToken, body, extraHeaders);

  return { ...res, correlationId: headerParams.correlationId };
}

import { randomUUID } from "node:crypto";
import type { Fx4CashInitiationParams } from "./cb-connect-fx4cash-shared.js";
import {
  defaultFx4CashProbeParams,
  FX4CASH_SANDBOX_INSTRUCTION_ID,
  FX4CASH_SANDBOX_MESSAGE_ID,
  FX4CASH_SANDBOX_PAYMENT_INFO_ID,
} from "./cb-connect-fx4cash-shared.js";
import { formatCbConnectApiTimestamp } from "./cb-connect-signing-core.js";

export type Fx4CashInitiationDocument = {
  customerCreditTransferInitiation: {
    groupHeader: {
      messageIdentification: string;
      creationDateTime: string;
      numberOfTransactions: number;
      controlSum: number;
      initiatingParty: {
        name: string;
        identification: {
          organisationIdentification: {
            anyBIC: string;
          };
        };
      };
    };
    paymentInformation: Array<{
      paymentInformationIdentification: string;
      paymentMethod: string;
      numberOfTransactions: number;
      batchBooking: boolean;
      controlSum: number;
      paymentTypeInformation: {
        serviceLevel: Array<{ code: string; proprietary: string }>;
      };
      requestedExecutionDate: { date: string };
      debtor: {
        name: string;
        postalAddress: {
          addressType: { code: string };
          department?: string;
          subDepartment?: string;
          streetName?: string;
          buildingNumber?: string;
          postCode?: string;
          townName?: string;
          countrySubDivision?: string;
          country: string;
          addressLine?: string[];
        };
      };
      debtorAccount: {
        identification: { other: { id: string } };
        currency: string;
      };
      debtorAgent: {
        financialInstitutionIdentification: {
          BICFI: string;
          name: string;
          postalAddress: { country: string; addressLine?: string[] };
        };
      };
      creditTransferTransactionInformation: Array<{
        paymentIdentification: {
          endToEndIdentification: string;
          instructionIdentification: string;
        };
        amount: {
          instructedAmount: { currency: string; amount: number };
        };
        creditor: {
          name: string;
          postalAddress: {
            addressType?: { code: string };
            department?: string;
            subDepartment?: string;
            streetName?: string;
            buildingNumber?: string;
            postCode?: string;
            townName?: string;
            countrySubDivision?: string;
            country: string;
            addressLine?: string[];
          };
          countryOfResidence?: string;
          contactDetails?: {
            name: string;
            emailAddress: string;
          };
        };
        creditorAccount: {
          identification:
            | { iban: string }
            | { other: { id: string } };
          currency: string;
        };
        creditorAgent: {
          financialInstitutionIdentification: {
            BICFI: string;
            name: string;
            postalAddress: { country: string; addressLine?: string[] };
          };
          branchIdentification?: { name: string };
        };
        remittanceInformation: { unstructured: string[] };
        relatedRemittanceInformation?: Array<{
          remittanceLocationDetails: Array<{
            method: string;
            electronicAddress: string;
          }>;
        }>;
      }>;
    }>;
  };
};

function mergeParams(
  overrides?: Partial<Fx4CashInitiationParams>
): Fx4CashInitiationParams {
  const base = defaultFx4CashProbeParams();
  const merged = { ...base, ...overrides };
  const now = new Date();

  return {
    ...merged,
    messageIdentification:
      merged.messageIdentification?.trim() ||
      randomUUID().replace(/-/g, ""),
    creationDateTime:
      merged.creationDateTime?.trim() || formatCbConnectApiTimestamp(now),
    controlSum: merged.controlSum ?? merged.instructedAmount ?? 0,
    paymentInformationIdentification:
      merged.paymentInformationIdentification?.trim() ||
      randomUUID().replace(/-/g, ""),
    requestedExecutionDate:
      merged.requestedExecutionDate?.trim() || now.toISOString().slice(0, 10),
    endToEndIdentification:
      merged.endToEndIdentification?.trim() ||
      randomUUID().replace(/-/g, "").slice(0, 35),
    instructionIdentification:
      merged.instructionIdentification?.trim() || FX4CASH_SANDBOX_INSTRUCTION_ID,
    debtorName: merged.debtorName?.trim() || "Debtor",
    debtorAccountId: merged.debtorAccountId?.trim() || "00000000",
    debtorAccountCurrency: merged.debtorAccountCurrency?.trim() || "EUR",
    debtorAgentBic: merged.debtorAgentBic?.trim() || "BKTRUS33XXX",
    debtorAgentName: merged.debtorAgentName?.trim() || "Deutsche Bank AG",
    debtorCountry: merged.debtorCountry?.trim() || "US",
    creditorName: merged.creditorName?.trim() || "Creditor",
    creditorIban: merged.creditorIban?.replace(/\s/g, "") || "",
    creditorAccountCurrency:
      merged.creditorAccountCurrency?.trim() || "USD",
    creditorCountry: merged.creditorCountry?.trim() || "US",
    creditorCountryOfResidence:
      merged.creditorCountryOfResidence?.trim() ||
      merged.creditorCountry?.trim() ||
      "US",
    creditorAgentBic: merged.creditorAgentBic?.trim() || "",
    creditorAgentName: merged.creditorAgentName?.trim() || "Bank",
    creditorAgentCountry:
      merged.creditorAgentCountry?.trim() || merged.creditorCountry?.trim(),
    remittanceUnstructured:
      merged.remittanceUnstructured?.trim() || "Payment",
    relatedRemittanceMethod: merged.relatedRemittanceMethod?.trim() || "URID",
    relatedRemittanceElectronicAddress:
      merged.relatedRemittanceElectronicAddress?.trim() ||
      "https://www.db.com",
  };
}

/** Exakter DB-Sandbox-Body (nur Zeitstempel / E2E dynamisch). */
export function buildFx4CashSandboxReferenceBody(
  now = new Date()
): Fx4CashInitiationDocument {
  return buildFx4CashInitiationBody(defaultFx4CashProbeParams(now));
}

export function buildFx4CashInitiationBody(
  overrides?: Partial<Fx4CashInitiationParams>
): Fx4CashInitiationDocument {
  const p = mergeParams(overrides);
  const controlSum = p.controlSum ?? p.instructedAmount ?? 0;

  const creditorPostal: NonNullable<
    Fx4CashInitiationDocument["customerCreditTransferInitiation"]["paymentInformation"][0]["creditTransferTransactionInformation"][0]["creditor"]["postalAddress"]
  > = {
    addressType: { code: "ADDR" },
    country: p.creditorCountry ?? "PF",
  };
  if (p.creditorDepartment) creditorPostal.department = p.creditorDepartment;
  if (p.creditorSubDepartment) creditorPostal.subDepartment = p.creditorSubDepartment;
  if (p.creditorStreetName) creditorPostal.streetName = p.creditorStreetName;
  if (p.creditorBuildingNumber) {
    creditorPostal.buildingNumber = p.creditorBuildingNumber;
  }
  if (p.creditorPostCode) creditorPostal.postCode = p.creditorPostCode;
  if (p.creditorTownName) creditorPostal.townName = p.creditorTownName;
  if (p.creditorCountrySubDivision) {
    creditorPostal.countrySubDivision = p.creditorCountrySubDivision;
  }
  if (p.creditorAddressLine) creditorPostal.addressLine = [p.creditorAddressLine];

  const creditorBlock: Fx4CashInitiationDocument["customerCreditTransferInitiation"]["paymentInformation"][0]["creditTransferTransactionInformation"][0]["creditor"] =
    {
      name: p.creditorName!,
      postalAddress: creditorPostal,
      countryOfResidence: p.creditorCountryOfResidence ?? p.creditorCountry,
    };
  if (p.creditorContactName && p.creditorContactEmail) {
    creditorBlock.contactDetails = {
      name: p.creditorContactName,
      emailAddress: p.creditorContactEmail,
    };
  }

  const creditorAgentBlock: Fx4CashInitiationDocument["customerCreditTransferInitiation"]["paymentInformation"][0]["creditTransferTransactionInformation"][0]["creditorAgent"] =
    {
      financialInstitutionIdentification: {
        BICFI: p.creditorAgentBic!,
        name: p.creditorAgentName || "Bank",
        postalAddress: {
          country: p.creditorAgentCountry ?? p.creditorCountry ?? "PF",
          ...(p.creditorAgentAddressLine || p.creditorAddressLine
            ? {
                addressLine: [
                  p.creditorAgentAddressLine ?? p.creditorAddressLine!,
                ],
              }
            : {}),
        },
      },
    };
  if (p.creditorBranchName) {
    creditorAgentBlock.branchIdentification = { name: p.creditorBranchName };
  }

  const creditTransfer: Fx4CashInitiationDocument["customerCreditTransferInitiation"]["paymentInformation"][0]["creditTransferTransactionInformation"][0] =
    {
      paymentIdentification: {
        endToEndIdentification: p.endToEndIdentification!,
        instructionIdentification: p.instructionIdentification!,
      },
      amount: {
        instructedAmount: {
          currency: p.instructedCurrency!,
          amount: p.instructedAmount ?? 0,
        },
      },
      creditor: creditorBlock,
      creditorAccount: p.creditorAccountId?.trim()
        ? {
            identification: { other: { id: p.creditorAccountId.trim() } },
            currency: p.creditorAccountCurrency!,
          }
        : {
            identification: { iban: p.creditorIban! },
            currency: p.creditorAccountCurrency!,
          },
      creditorAgent: creditorAgentBlock,
      remittanceInformation: {
        unstructured: [p.remittanceUnstructured!],
      },
    };

  if (p.relatedRemittanceMethod && p.relatedRemittanceElectronicAddress) {
    creditTransfer.relatedRemittanceInformation = [
      {
        remittanceLocationDetails: [
          {
            method: p.relatedRemittanceMethod,
            electronicAddress: p.relatedRemittanceElectronicAddress,
          },
        ],
      },
    ];
  }

  return {
    customerCreditTransferInitiation: {
      groupHeader: {
        messageIdentification: p.messageIdentification!,
        creationDateTime: p.creationDateTime!,
        numberOfTransactions: 1,
        controlSum,
        initiatingParty: {
          name: p.initiatingPartyName!,
          identification: {
            organisationIdentification: {
              anyBIC: p.initiatingPartyBic!,
            },
          },
        },
      },
      paymentInformation: [
        {
          paymentInformationIdentification: p.paymentInformationIdentification!,
          paymentMethod: "TRF",
          numberOfTransactions: 1,
          batchBooking: false,
          controlSum,
          paymentTypeInformation: {
            serviceLevel: [
              { code: "G001", proprietary: "PRIORITY-TRANSFER" },
            ],
          },
          requestedExecutionDate: { date: p.requestedExecutionDate! },
          debtor: {
            name: p.debtorName!,
            postalAddress: {
              addressType: { code: "ADDR" },
              department: p.debtorDepartment,
              subDepartment: p.debtorSubDepartment,
              streetName: p.debtorStreetName,
              buildingNumber: p.debtorBuildingNumber,
              postCode: p.debtorPostCode,
              townName: p.debtorTownName,
              countrySubDivision: p.debtorCountrySubDivision,
              country: p.debtorCountry ?? "US",
              addressLine: p.debtorAddressLine
                ? [p.debtorAddressLine]
                : undefined,
            },
          },
          debtorAccount: {
            identification: { other: { id: p.debtorAccountId! } },
            currency: p.debtorAccountCurrency!,
          },
          debtorAgent: {
            financialInstitutionIdentification: {
              BICFI: p.debtorAgentBic!,
              name: p.debtorAgentName!,
              postalAddress: {
                country: p.debtorCountry ?? "US",
                addressLine: p.debtorAgentAddressLine
                  ? [p.debtorAgentAddressLine]
                  : undefined,
              },
            },
          },
          creditTransferTransactionInformation: [creditTransfer],
        },
      ],
    },
  };
}

export function formatFx4CashInitiationJson(
  overrides?: Partial<Fx4CashInitiationParams>,
  options?: { sandboxReference?: boolean }
): string {
  const body = options?.sandboxReference
    ? buildFx4CashSandboxReferenceBody()
    : buildFx4CashInitiationBody(overrides);
  return JSON.stringify(body, null, 2);
}

export function formatFx4CashSandboxReferenceJson(now = new Date()): string {
  return JSON.stringify(buildFx4CashSandboxReferenceBody(now), null, 2);
}

/** Prüft, ob Params dem DB-Referenz-Szenario entsprechen (für Tests). */
export function isFx4CashSandboxReferenceParams(
  params: Partial<Fx4CashInitiationParams>
): boolean {
  return (
    params.messageIdentification === FX4CASH_SANDBOX_MESSAGE_ID &&
    params.paymentInformationIdentification === FX4CASH_SANDBOX_PAYMENT_INFO_ID
  );
}

/** Extrahiert bekannte Felder aus FX4Cash JSON-Antworten (Initiierung / Status-Report). */

function deepFindString(
  node: unknown,
  keys: string[],
  depth = 0
): string | undefined {
  if (depth > 12 || node == null) return undefined;
  if (typeof node === "object" && !Array.isArray(node)) {
    const rec = node as Record<string, unknown>;
    for (const key of keys) {
      const v = rec[key];
      if (typeof v === "string" && v.trim()) return v.trim();
    }
    for (const v of Object.values(rec)) {
      const found = deepFindString(v, keys, depth + 1);
      if (found) return found;
    }
  }
  if (Array.isArray(node)) {
    for (const item of node) {
      const found = deepFindString(item, keys, depth + 1);
      if (found) return found;
    }
  }
  return undefined;
}

export type Fx4CashInitiationParsed = {
  serviceRequestId?: string;
  endToEndIdentification?: string;
  messageIdentification?: string;
};

export function parseFx4CashInitiationResponse(
  body: string
): Fx4CashInitiationParsed {
  try {
    const json = JSON.parse(body) as unknown;
    return {
      serviceRequestId: deepFindString(json, [
        "serviceRequestId",
        "service-request-identifier",
        "serviceRequestIdentifier",
        "service-request-id",
      ]),
      endToEndIdentification: deepFindString(json, [
        "endToEndIdentification",
        "endToEndId",
      ]),
      messageIdentification: deepFindString(json, [
        "messageIdentification",
        "messageId",
      ]),
    };
  } catch {
    return {};
  }
}

export type Fx4CashStatusReportInput = {
  debtorIban: string;
  endToEndIdentification: string;
};

export function buildFx4CashStatusReportBody(
  input: Fx4CashStatusReportInput
): { debtorAccount: { iban: string }; endToEndIdentification: string } {
  return {
    debtorAccount: {
      iban: input.debtorIban.replace(/\s/g, "").toUpperCase(),
    },
    endToEndIdentification: input.endToEndIdentification.trim(),
  };
}

export function formatFx4CashStatusReportJson(
  input: Fx4CashStatusReportInput
): string {
  return JSON.stringify(buildFx4CashStatusReportBody(input), null, 2);
}

export type Fx4CashStatusReportParsed = {
  transactionStatus?: string;
  serviceRequestId?: string;
  endToEndIdentification?: string;
  summary?: string;
};

export function parseFx4CashStatusReportResponse(
  body: string
): Fx4CashStatusReportParsed {
  try {
    const json = JSON.parse(body) as unknown;
    const transactionStatus = deepFindString(json, [
      "transactionStatus",
      "paymentStatus",
      "status",
      "transactionIndividualStatus",
    ]);
    const serviceRequestId = deepFindString(json, [
      "serviceRequestId",
      "service-request-identifier",
      "serviceRequestIdentifier",
    ]);
    const endToEndIdentification = deepFindString(json, [
      "endToEndIdentification",
      "endToEndId",
    ]);

    const parts = [
      transactionStatus ? `Status: ${transactionStatus}` : null,
      serviceRequestId ? `Service-ID: ${serviceRequestId}` : null,
      endToEndIdentification ? `E2E: ${endToEndIdentification}` : null,
    ].filter(Boolean);

    return {
      transactionStatus,
      serviceRequestId,
      endToEndIdentification,
      summary: parts.length > 0 ? parts.join(" · ") : undefined,
    };
  } catch {
    return {};
  }
}

import {
  cbConnectFetchAccessToken,
  cbConnectSignedPostResult,
} from "./cb-connect-client.js";
import {
  formatFx4CashInitiationJson,
} from "./cb-connect-fx4cash-build.js";
import {
  formatFx4CashStatusReportJson,
  parseFx4CashInitiationResponse,
  parseFx4CashStatusReportResponse,
  type Fx4CashStatusReportInput,
} from "./cb-connect-fx4cash-parse.js";
import type { Fx4CashInitiationParams } from "./cb-connect-fx4cash-shared.js";
import {
  parseFx4CashValueDateAccepted,
  parseFx4CashValueDateResponse,
} from "./cb-connect-fx4cash-value-date-parse.js";
import {
  defaultFx4CashValueDateParams,
  formatFx4CashValueDateJson,
  FX4CASH_VALUE_DATE_PROBE_SCENARIOS,
  type Fx4CashValueDateParams,
  type Fx4CashValueDateScenario,
} from "./cb-connect-fx4cash-value-date-shared.js";
import {
  createFx4CashCorrelationId,
  formatCbConnectApiTimestamp,
  formatProbeRequestHeaders,
  formatProbeResponseJson,
  resolveFx4CashCorrelationPair,
} from "./cb-connect-signing-core.js";
import { cbConnectEndpointsGetPublic } from "./endpoints-store.js";
import {
  nativeBankGetResolvedCredentials,
  validateCredentialsForBankingApi,
} from "./resolved-credentials.js";

export type Fx4CashInitiationResult =
  | {
      ok: true;
      status: number;
      correlationId: string;
      responseJson: string;
      requestJson: string;
      serviceRequestId?: string;
      endToEndIdentification?: string;
    }
  | {
      ok: false;
      error: string;
      status?: number;
      correlationId?: string;
      responseJson?: string;
      requestJson?: string;
    };

export type Fx4CashStatusReportResult =
  | {
      ok: true;
      status: number;
      correlationId: string;
      responseJson: string;
      requestJson: string;
      transactionStatus?: string;
      serviceRequestId?: string;
      summary?: string;
    }
  | {
      ok: false;
      error: string;
      status?: number;
      correlationId?: string;
      responseJson?: string;
      requestJson?: string;
    };

async function resolveFx4CashBanking(teamId: string) {
  const creds = await nativeBankGetResolvedCredentials(teamId);
  const bankingErr = validateCredentialsForBankingApi(creds);
  if (bankingErr) return { ok: false as const, error: bankingErr };

  const endpoints = await cbConnectEndpointsGetPublic(teamId);
  const { accessToken } = await cbConnectFetchAccessToken(
    creds,
    endpoints.oauthTokenUrl
  );

  return { ok: true as const, creds, accessToken, endpoints };
}

function prepareFx4CashInitiationRequest(
  params?: Partial<Fx4CashInitiationParams>
): {
  requestJson: string;
  correlationId: string;
  endToEndIdentification: string;
} {
  const pair = resolveFx4CashCorrelationPair(params?.endToEndIdentification);
  const requestJson = formatFx4CashInitiationJson({
    ...params,
    endToEndIdentification: pair.endToEndIdentification,
  });
  return {
    requestJson,
    correlationId: pair.correlationId,
    endToEndIdentification: pair.endToEndIdentification,
  };
}

export async function cbConnectFx4CashInitiate(
  teamId: string,
  params?: Partial<Fx4CashInitiationParams>,
  options?: { allowErrorStatus?: boolean }
): Promise<Fx4CashInitiationResult> {
  const tid = teamId?.trim();
  if (!tid) return { ok: false, error: "Team-ID fehlt." };

  const prepared = prepareFx4CashInitiationRequest(params);
  const { requestJson, correlationId, endToEndIdentification } = prepared;
  const ctx = await resolveFx4CashBanking(tid);
  if (!ctx.ok) {
    return { ok: false, error: ctx.error, requestJson };
  }

  const initiationUrl = ctx.endpoints.fx4CashInitiationUrl.trim();
  if (!initiationUrl) {
    return {
      ok: false,
      error: "FX4Cash-Initiierungs-URL ist nicht konfiguriert.",
      requestJson,
    };
  }
  const extraHeaders = {
    "x-customer-identifier": ctx.creds.xCustomerIdentifier,
    "x-correlation-identifier": correlationId,
    "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
  };

  try {
    const res = await cbConnectSignedPostResult(
      ctx.creds,
      initiationUrl,
      ctx.accessToken,
      requestJson,
      extraHeaders
    );

    const responseJson = formatProbeResponseJson(res.body);
    const parsed = parseFx4CashInitiationResponse(res.body);
    const okHttp = res.status >= 200 && res.status < 300;

    if (!okHttp && !options?.allowErrorStatus) {
      return {
        ok: false,
        error: `FX4Cash Initiierung fehlgeschlagen (HTTP ${res.status})`,
        status: res.status,
        correlationId,
        responseJson,
        requestJson,
      };
    }

    if (!okHttp) {
      return {
        ok: false,
        error: `FX4Cash Initiierung: HTTP ${res.status}`,
        status: res.status,
        correlationId,
        responseJson,
        requestJson,
      };
    }

    return {
      ok: true,
      status: res.status,
      correlationId,
      responseJson,
      requestJson,
      serviceRequestId: parsed.serviceRequestId,
      endToEndIdentification:
        parsed.endToEndIdentification ?? endToEndIdentification,
    };
  } catch (e) {
    return {
      ok: false,
      error: e instanceof Error ? e.message : "FX4Cash Initiierung fehlgeschlagen.",
      correlationId,
      requestJson,
    };
  }
}

export async function cbConnectFx4CashStatusReport(
  teamId: string,
  input: Fx4CashStatusReportInput
): Promise<Fx4CashStatusReportResult> {
  const tid = teamId?.trim();
  if (!tid) return { ok: false, error: "Team-ID fehlt." };

  const iban = input.debtorIban?.replace(/\s/g, "").trim();
  const e2e = input.endToEndIdentification?.trim();
  if (!iban) {
    return { ok: false, error: "Debtor-IBAN fehlt (für Status-Enquiry)." };
  }
  if (!e2e) {
    return { ok: false, error: "End-to-End-ID fehlt (für Status-Enquiry)." };
  }

  const requestJson = formatFx4CashStatusReportJson({ debtorIban: iban, endToEndIdentification: e2e });
  const ctx = await resolveFx4CashBanking(tid);
  if (!ctx.ok) {
    return { ok: false, error: ctx.error, requestJson };
  }

  const statusUrl = ctx.endpoints.fx4CashStatusReportUrl.trim();
  if (!statusUrl) {
    return {
      ok: false,
      error: "FX4Cash Status-Report-URL ist nicht konfiguriert.",
      requestJson,
    };
  }

  const correlationId = createFx4CashCorrelationId();
  const extraHeaders = {
    "x-customer-identifier": ctx.creds.xCustomerIdentifier,
    "x-correlation-identifier": correlationId,
    "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
  };

  try {
    const res = await cbConnectSignedPostResult(
      ctx.creds,
      statusUrl,
      ctx.accessToken,
      requestJson,
      extraHeaders
    );

    const responseJson = formatProbeResponseJson(res.body);
    const parsed = parseFx4CashStatusReportResponse(res.body);
    const okHttp = res.status >= 200 && res.status < 300;

    if (!okHttp) {
      return {
        ok: false,
        error: `FX4Cash Status-Enquiry: HTTP ${res.status}`,
        status: res.status,
        correlationId,
        responseJson,
        requestJson,
      };
    }

    return {
      ok: true,
      status: res.status,
      correlationId,
      responseJson,
      requestJson,
      transactionStatus: parsed.transactionStatus,
      serviceRequestId: parsed.serviceRequestId,
      summary: parsed.summary,
    };
  } catch (e) {
    return {
      ok: false,
      error:
        e instanceof Error ? e.message : "FX4Cash Status-Enquiry fehlgeschlagen.",
      correlationId,
      requestJson,
    };
  }
}

export async function cbConnectFx4CashStatusReportProbe(
  teamId: string,
  _statusReportUrl: string,
  _oauthTokenUrl: string,
  input: Fx4CashStatusReportInput
): Promise<
  | {
      ok: true;
      status: number;
      message: string;
      requestJson: string;
      responseJson: string;
      requestHeadersJson?: string;
    }
  | {
      ok: false;
      error: string;
      requestJson?: string;
      responseJson?: string;
      requestHeadersJson?: string;
    }
> {
  const result = await cbConnectFx4CashStatusReport(teamId, input);
  if (!result.ok) {
    return {
      ok: false,
      error: result.error,
      requestJson: result.requestJson,
      responseJson: result.responseJson,
    };
  }

  const msg = result.summary
    ? `Status-Enquiry OK (HTTP ${result.status}): ${result.summary}`
    : `Status-Enquiry OK (HTTP ${result.status}, Correlation: ${result.correlationId})`;

  return {
    ok: true,
    status: result.status,
    message: msg,
    requestJson: result.requestJson,
    responseJson: result.responseJson,
    requestHeadersJson: undefined,
  };
}

export async function cbConnectFx4CashProbe(
  teamId: string,
  initiationUrl: string,
  oauthTokenUrl: string,
  params?: Partial<Fx4CashInitiationParams>
): Promise<
  | {
      ok: true;
      status: number;
      message: string;
      requestJson: string;
      responseJson: string;
      requestHeadersJson?: string;
      correlationId?: string;
      endToEndIdentification?: string;
    }
  | {
      ok: false;
      error: string;
      requestJson?: string;
      responseJson?: string;
      requestHeadersJson?: string;
      correlationId?: string;
      endToEndIdentification?: string;
    }
> {
  const prepared = prepareFx4CashInitiationRequest(params);
  const { requestJson, correlationId, endToEndIdentification } = prepared;
  const url = initiationUrl.trim() || (await cbConnectEndpointsGetPublic(teamId)).fx4CashInitiationUrl;

  const creds = await nativeBankGetResolvedCredentials(teamId);
  const bankingErr = validateCredentialsForBankingApi(creds);
  if (bankingErr) {
    return {
      ok: false,
      error: bankingErr,
      requestJson,
      correlationId,
      endToEndIdentification,
    };
  }

  try {
    const { accessToken } = await cbConnectFetchAccessToken(
      creds,
      oauthTokenUrl.trim() || (await cbConnectEndpointsGetPublic(teamId)).oauthTokenUrl
    );
    const extraHeaders = {
      "x-customer-identifier": creds.xCustomerIdentifier,
      "x-correlation-identifier": correlationId,
      "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
    };

    const res = await cbConnectSignedPostResult(
      creds,
      url,
      accessToken,
      requestJson,
      extraHeaders
    );

    const responseJson = formatProbeResponseJson(res.body);
    const requestHeadersJson = formatProbeRequestHeaders(res.requestHeaders);
    const okHttp = res.status >= 200 && res.status < 300;

    if (!okHttp) {
      return {
        ok: false,
        error: `FX4Cash (positiver Fall): HTTP ${res.status}`,
        requestJson,
        responseJson,
        requestHeadersJson,
        correlationId,
        endToEndIdentification,
      };
    }

    return {
      ok: true,
      status: res.status,
      message: `FX4Cash Initiierung erfolgreich (HTTP ${res.status}, E2E: ${endToEndIdentification}, Correlation: ${correlationId})`,
      requestJson,
      responseJson,
      requestHeadersJson,
      correlationId,
      endToEndIdentification,
    };
  } catch (e) {
    return {
      ok: false,
      error: e instanceof Error ? e.message : "FX4Cash-Test fehlgeschlagen.",
      requestJson,
      correlationId,
      endToEndIdentification,
    };
  }
}

function evaluateFx4CashValueDateProbeOutcome(
  scenario: Fx4CashValueDateScenario,
  status: number,
  body: string
): { ok: boolean; message: string } {
  const meta = FX4CASH_VALUE_DATE_PROBE_SCENARIOS.find((s) => s.id === scenario);
  const label = meta?.label ?? scenario;
  const accepted = parseFx4CashValueDateAccepted(body);

  if (scenario === "notFound") {
    if (status === 404) {
      return {
        ok: true,
        message: `Evaluate (${label}): HTTP 404 wie erwartet`,
      };
    }
    return {
      ok: false,
      message: `Evaluate (${label}): erwartet HTTP 404, erhalten ${status}`,
    };
  }

  if (scenario === "dateRejected") {
    if (status === 404) {
      return {
        ok: false,
        message: `Evaluate (${label}): unerwartet HTTP 404`,
      };
    }
    if (accepted === false) {
      return {
        ok: true,
        message: `Evaluate (${label}): Valuta abgelehnt (HTTP ${status})`,
      };
    }
    if (accepted === true) {
      return {
        ok: false,
        message: `Evaluate (${label}): erwartet Ablehnung, Antwort zeigt Annahme`,
      };
    }
    if (status >= 200 && status < 300) {
      return {
        ok: true,
        message: `Evaluate (${label}): HTTP ${status} — Antwort prüfen (kein Annahme-Flag)`,
      };
    }
    return {
      ok: true,
      message: `Evaluate (${label}): HTTP ${status}`,
    };
  }

  if (status >= 200 && status < 300) {
    if (accepted === false) {
      return {
        ok: false,
        message: `Evaluate (${label}): erwartet Annahme, Valuta abgelehnt`,
      };
    }
    return {
      ok: true,
      message: `Evaluate (${label}): Valuta bestätigt (HTTP ${status})`,
    };
  }

  return {
    ok: false,
    message: `Evaluate (${label}): erwartet HTTP 2xx, erhalten ${status}`,
  };
}

export type Fx4CashValueDateEvaluateResult =
  | {
      ok: true;
      status: number;
      correlationId: string;
      accepted?: boolean;
      creditDate?: string;
      message: string;
      requestJson: string;
      responseJson: string;
    }
  | {
      ok: false;
      error: string;
      status?: number;
      correlationId?: string;
      requestJson?: string;
      responseJson?: string;
    };

function formatValueDateEvaluateMessage(
  status: number,
  accepted: boolean | undefined,
  creditDate: string | undefined,
  suggestedValueDate: string
): string {
  if (status === 404) {
    return "Währungspaar oder Konto für Evaluate nicht gefunden (HTTP 404).";
  }
  if (status < 200 || status >= 300) {
    return `Evaluate fehlgeschlagen (HTTP ${status}).`;
  }
  if (accepted === false) {
    return "Valutadatum vom Bankensystem nicht akzeptiert.";
  }
  const date = creditDate ?? suggestedValueDate;
  if (accepted === true || creditDate) {
    return `Gutschrift voraussichtlich am ${date}.`;
  }
  return "Evaluate erfolgreich — Gutschriftstag in der Antwort prüfen.";
}

export async function cbConnectFx4CashEvaluateValueDate(
  teamId: string,
  params: Fx4CashValueDateParams
): Promise<Fx4CashValueDateEvaluateResult> {
  const tid = teamId?.trim();
  if (!tid) return { ok: false, error: "Team-ID fehlt." };

  const accountNumber = params.accountNumber?.trim();
  const currencyPair = params.currencyPair?.trim().toUpperCase();
  const suggestedValueDate = params.suggestedValueDate?.trim();
  if (!accountNumber || !currencyPair || !suggestedValueDate) {
    return {
      ok: false,
      error:
        "Abbuchungskonto, Währungspaar und Valutadatum sind für Evaluate erforderlich.",
    };
  }

  const normalized: Fx4CashValueDateParams = {
    accountNumber,
    currencyPair,
    suggestedValueDate,
  };
  const requestJson = formatFx4CashValueDateJson(normalized);

  const ctx = await resolveFx4CashBanking(tid);
  if (!ctx.ok) {
    return { ok: false, error: ctx.error, requestJson };
  }

  const url = ctx.endpoints.fx4CashValueDateUrl;
  const correlationId = createFx4CashCorrelationId();

  try {
    const res = await cbConnectSignedPostResult(
      ctx.creds,
      url,
      ctx.accessToken,
      requestJson,
      {
        "x-customer-identifier": ctx.creds.xCustomerIdentifier,
        "x-correlation-identifier": correlationId,
        "x-apiConsumer-request-timestamp": formatCbConnectApiTimestamp(),
      }
    );

    const responseJson = formatProbeResponseJson(res.body);
    const parsed = parseFx4CashValueDateResponse(res.body);
    const message = formatValueDateEvaluateMessage(
      res.status,
      parsed.accepted,
      parsed.creditDate,
      suggestedValueDate
    );

    if (res.status === 404 || res.status < 200 || res.status >= 300) {
      return {
        ok: false,
        error: message,
        status: res.status,
        correlationId,
        requestJson,
        responseJson,
      };
    }

    if (parsed.accepted === false) {
      return {
        ok: false,
        error: message,
        status: res.status,
        correlationId,
        requestJson,
        responseJson,
      };
    }

    return {
      ok: true,
      status: res.status,
      correlationId,
      accepted: parsed.accepted,
      creditDate: parsed.creditDate ?? suggestedValueDate,
      message,
      requestJson,
      responseJson,
    };
  } catch (e) {
    return {
      ok: false,
      error:
        e instanceof Error ? e.message : "FX4Cash Evaluate fehlgeschlagen.",
      requestJson,
      correlationId,
    };
  }
}

