function asRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === "object" ? (v as Record<string, unknown>) : null;
}

export function parseFinapiBankConnections(
  raw: unknown
): FinapiBankConnectionSummary[] {
  const root = asRecord(raw);
  const list = Array.isArray(root?.connections)
    ? root!.connections
    : Array.isArray(root?.bankConnections)
      ? root!.bankConnections
      : Array.isArray(raw)
        ? raw
        : [];

  const now = Date.now();
  return list
    .map((item): FinapiBankConnectionSummary | null => {
      const o = asRecord(item);
      if (!o || typeof o.id !== "number") return null;
      const bank = asRecord(o.bank);
      return {
        id: o.id,
        name: typeof o.name === "string" ? o.name : `Verbindung ${o.id}`,
        bankName:
          typeof bank?.name === "string"
            ? bank.name
            : typeof o.bankName === "string"
              ? o.bankName
              : null,
        updatedAt: now,
      };
    })
    .filter((x): x is FinapiBankConnectionSummary => x !== null);
}

export function parseFinapiAccounts(raw: unknown): FinapiAccountSummary[] {
  const root = asRecord(raw);
  const list = Array.isArray(root?.accounts)
    ? root!.accounts
    : Array.isArray(raw)
      ? raw
      : [];

  const now = Date.now();
  return list
    .map((item): FinapiAccountSummary | null => {
      const o = asRecord(item);
      if (!o || typeof o.id !== "number") return null;
      const balance = asRecord(o.balance);
      return {
        id: o.id,
        name:
          typeof o.accountName === "string" ? o.accountName : `Konto ${o.id}`,
        iban: typeof o.iban === "string" ? o.iban : null,
        accountType: typeof o.accountType === "string" ? o.accountType : null,
        balance:
          typeof balance?.value === "number"
            ? balance.value
            : typeof o.balance === "number"
              ? o.balance
              : null,
        currency:
          typeof balance?.currency === "string"
            ? balance.currency
            : typeof o.currency === "string"
              ? o.currency
              : null,
        bankConnectionId:
          typeof o.bankConnectionId === "number" ? o.bankConnectionId : null,
        syncedAt: now,
      };
    })
    .filter((x): x is FinapiAccountSummary => x !== null);
}

import type {
  FinapiCreateUserResponse,
  FinapiEndpoints,
  FinapiTokenResponse,
  FinapiWebFormResponse,
} from "./shared.js";

export class FinapiApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string
  ) {
    super(message);
    this.name = "FinapiApiError";
  }

  detailMessage(): string {
    try {
      const parsed = JSON.parse(this.body) as {
        errors?: Array<{ field?: string; message?: string }>;
        description?: string;
        code?: string;
      };
      if (parsed.errors?.length) {
        return parsed.errors
          .map((e) => [e.field, e.message].filter(Boolean).join(": "))
          .join("; ");
      }
      if (parsed.description) return parsed.description;
      if (parsed.code) return parsed.code;
    } catch {
      /* ignore */
    }
    return this.body.trim().slice(0, 240);
  }
}

/** finAPI 422 when redirectUrl/callbacks require a licensed mandator (common in sandbox). */
export function finapiIsRedirectUrlLicenseError(e: unknown): boolean {
  if (!(e instanceof FinapiApiError) || e.status !== 422) return false;
  const haystack = `${e.detailMessage()} ${e.body}`.toLowerCase();
  return (
    haystack.includes("redirecturl") &&
    (haystack.includes("unlicensed") || haystack.includes("not allowed"))
  );
}

function isHttpsUrl(url: string): boolean {
  try {
    return new URL(url).protocol === "https:";
  } catch {
    return false;
  }
}

async function readErrorBody(res: Response): Promise<string> {
  try {
    return (await res.text()).slice(0, 500);
  } catch {
    return "";
  }
}

