  });

  if (!res.ok) {
    throw new FinapiApiError(
      `finAPI Client-Token fehlgeschlagen (HTTP ${res.status})`,
      res.status,
      await readErrorBody(res)
    );
  }

  return (await res.json()) as FinapiTokenResponse;
}

