    moneyTransfers: params.moneyTransfers.map((o) => ({
      counterpartName: o.counterpartName,
      counterpartIban: o.counterpartIban.replace(/\s/g, ""),
      ...(o.counterpartBic?.trim()
        ? { counterpartBic: o.counterpartBic.replace(/\s/g, "").toUpperCase() }
        : {}),
      amount: o.amount,
