/**
 * SME Deutsche Bank Connector — credentials from server env (no team store).
 */

import {
  smeDbEndpointsForEnvironment,
  type SmeDbEndpoints,
  type SmeDbEnvironment,
} from "./shared.js";

export type SmeDbEnvCredentials = {
  clientId: string;
  clientSecret: string;
  refreshToken: string;
  environment: SmeDbEnvironment;
  publicOrigin: string | null;
  endpoints: SmeDbEndpoints;
};

function env(key: string): string {
  const direct = (process.env[key] ?? "").trim();
  if (direct) return direct;
  for (const [k, v] of Object.entries(process.env)) {
    if (k.trim() === key && typeof v === "string") return v.trim();
  }
  return "";
}

export function readSmeDbEnvironment(): SmeDbEnvironment {
  const raw = (env("SME_DB_ENVIRONMENT") || env("DEUTSCHE_BANK_BIZ_ENVIRONMENT")).toLowerCase();
  return raw === "live" ? "live" : "sandbox";
}

export function readSmeDbPublicOrigin(): string | null {
  const candidates = [
    env("SME_DB_PUBLIC_ORIGIN"),
    env("DEUTSCHE_BANK_BIZ_PUBLIC_ORIGIN"),
    process.env.NEXT_PUBLIC_APP_URL?.trim() ?? "",
    process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : "",
  ].filter(Boolean);

  for (const raw of candidates) {
    try {
      const url = new URL(raw.startsWith("http") ? raw : `https://${raw}`);
      if (url.protocol === "https:" || url.hostname === "localhost") {
        return url.origin;
      }
    } catch {
      /* next */
    }
  }
  return null;
}

export function readSmeDbEnv(): SmeDbEnvCredentials {
  const environment = readSmeDbEnvironment();
  return {
    clientId:
      env("SME_DB_CLIENT_ID") ||
      env("CASH365_BIZBANK_CLIENT_ID") ||
      env("CASH365_BIZ_BANK_CLIENT_ID") ||
      env("Cash365BizBankClientId") ||
      env("DEUTSCHE_BANK_BIZ_CLIENT_ID"),
    clientSecret:
      env("SME_DB_CLIENT_SECRET") ||
      env("CASH365_BIZBANK_CLIENT_SECRET") ||
      env("Cash365BizBankClientSecret") ||
      env("DEUTSCHE_BANK_BIZ_CLIENT_SECRET"),
    refreshToken:
      env("SME_DB_REFRESH_TOKEN") ||
      env("DEUTSCHE_BANK_BIZ_REFRESH_TOKEN"),
    environment,
    publicOrigin: readSmeDbPublicOrigin(),
    endpoints: smeDbEndpointsForEnvironment(environment),
  };
}

export function hasSmeDbEnv(): boolean {
  const e = readSmeDbEnv();
  return Boolean(e.clientId || e.clientSecret || e.refreshToken);
}

export function smeDbOAuthCallbackPath(): string {
  return "/api/sme-db-oauth/callback";
}

import { randomUUID } from "node:crypto";
import {
  buildSmeDbAuthorizeUrl,
  type SmeDbTokenResponse,
} from "./shared.js";
import {
  smeDbGetResolvedCredentials,
  validateSmeDbClientCredentials,
  validateSmeDbUserSession,
  type SmeDbResolvedCredentials,
} from "./resolved-credentials.js";
import { smeDbOAuthCallbackPath } from "./env-config.js";

export class SmeDbApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string
  ) {
    super(message);
    this.name = "SmeDbApiError";
  }
}

export function basicAuthHeader(clientId: string, clientSecret: string): string {
  return `Basic ${Buffer.from(`${clientId}:${clientSecret}`, "utf8").toString("base64")}`;
}

const tokenCacheState: { token: string; expiresAt: number } = {
  token: "",
  expiresAt: 0,
};

export function clearSmeDbTokenCache(): void {
  tokenCacheState.token = "";
  tokenCacheState.expiresAt = 0;
}

export function randomOAuthState(): string {
  return randomUUID().replace(/[{}-]/g, "");
}

export type SmeDbAuthorizeProbeResult =
  | { ok: true }
  | { ok: false; code: string; detail: string };

/** Kurztest vor dem Browser-Redirect — vermeidet rohe XML-Fehlerseiten der DB. */
export async function probeSmeDbAuthorizeReachability(
  authorizeUrl: string
): Promise<SmeDbAuthorizeProbeResult> {
  let res: Response;
  try {
    res = await fetch(authorizeUrl, {
      method: "GET",
      redirect: "manual",
      headers: {
        Accept:
          "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
      },
      signal: AbortSignal.timeout(12_000),
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : "Netzwerkfehler";
    return { ok: false, code: "db_authorize_unreachable", detail: msg };
  }

  const text = (await res.text()).trim();

  if (text.includes("Not able to fetch ACR value")) {
    const isLive = authorizeUrl.includes("api.db.com/gw/oidc");
    return {
      ok: false,
      code: "db_acr_not_configured",
      detail: isLive
        ? "Die Client-ID ist für Live (api.db.com) nicht freigeschaltet — Production-Zugang beantragen oder Simulator-URLs nutzen."
        : "Die Deutsche Bank konnte keinen ACR-Wert für diese Client-ID laden — App-Konfiguration prüfen.",
    };
  }

  if (res.status === 404) {
    return {
      ok: false,
      code: "db_authorize_not_found",
      detail:
        "Authorization-Endpunkt antwortet mit 404 — Simulator ggf. nicht verfügbar; Live-Defaults prüfen.",
    };
  }

  if (res.status >= 300 && res.status < 400) return { ok: true };
  if (res.status >= 200 && res.status < 300 && !text.startsWith("<root>")) {
    return { ok: true };
  }

  if (res.status >= 400 || text.startsWith("<root>")) {
    const snippet = text.replace(/\s+/g, " ").slice(0, 180);
    return {
      ok: false,
      code: "db_authorize_error",
      detail: snippet || `HTTP ${res.status}`,
    };
  }

  return { ok: true };
}

function resolveRedirectUri(
  creds: SmeDbResolvedCredentials,
  redirectUri?: string
): string {
  if (redirectUri?.trim()) return redirectUri.trim();
  if (creds.publicOrigin) {
    return `${creds.publicOrigin}${smeDbOAuthCallbackPath()}`;
  }
  throw new Error(
    "redirectUri fehlt — explizit übergeben oder SME_DB_PUBLIC_ORIGIN setzen."
  );
}

export async function exchangeSmeDbAuthorizationCode(
  code: string,
  redirectUri?: string
): Promise<SmeDbTokenResponse> {
  const creds = smeDbGetResolvedCredentials();
  const err = validateSmeDbClientCredentials(creds);
  if (err) throw new Error(err);
  const uri = resolveRedirectUri(creds, redirectUri);

  const body = new URLSearchParams({
    grant_type: "authorization_code",
    code,
    redirect_uri: uri,
  });

  const res = await fetch(creds.endpoints.tokenUrl, {
    method: "POST",
    headers: {
      Authorization: basicAuthHeader(creds.clientId, creds.clientSecret),
      "Content-Type": "application/x-www-form-urlencoded",
      Accept: "application/json",
    },
    body,
    signal: AbortSignal.timeout(30_000),
  });

  const text = await res.text();
  if (!res.ok) {
    throw new SmeDbApiError(
      `Token-Austausch fehlgeschlagen (HTTP ${res.status})`,
      res.status,
      text.slice(0, 800)
    );
  }

  let json: SmeDbTokenResponse;
  try {
    json = JSON.parse(text) as SmeDbTokenResponse;
  } catch {
    throw new Error("Token-Antwort ist kein gültiges JSON.");
  }
  if (!json.access_token) {
    throw new Error("access_token fehlt in der Token-Antwort.");
  }

  const expiresIn =
    typeof json.expires_in === "number" && json.expires_in > 0
      ? json.expires_in
      : 600;
  tokenCacheState.token = json.access_token;
  tokenCacheState.expiresAt = Date.now() + expiresIn * 1000 - 30_000;

  return json;
}

export async function getSmeDbAccessToken(redirectUri?: string): Promise<string> {
  if (tokenCacheState.token && tokenCacheState.expiresAt > Date.now()) {
    return tokenCacheState.token;
  }

  const creds = smeDbGetResolvedCredentials();
  const err = validateSmeDbUserSession(creds);
  if (err) throw new Error(err);
  const uri = resolveRedirectUri(creds, redirectUri);

  const body = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: creds.refreshToken,
    redirect_uri: uri,
  });

  const res = await fetch(creds.endpoints.tokenUrl, {
    method: "POST",
    headers: {
      Authorization: basicAuthHeader(creds.clientId, creds.clientSecret),
      "Content-Type": "application/x-www-form-urlencoded",
      Accept: "application/json",
    },
    body,
    signal: AbortSignal.timeout(30_000),
  });

  const text = await res.text();
  if (!res.ok) {
    throw new SmeDbApiError(
      `Refresh-Token fehlgeschlagen (HTTP ${res.status})`,
      res.status,
      text.slice(0, 800)
    );
  }

  let json: SmeDbTokenResponse;
  try {
    json = JSON.parse(text) as SmeDbTokenResponse;
  } catch {
    throw new Error("Token-Antwort ist kein gültiges JSON.");
  }
  if (!json.access_token) {
    throw new Error("access_token fehlt in der Refresh-Antwort.");
  }

  const expiresIn =
    typeof json.expires_in === "number" && json.expires_in > 0
      ? json.expires_in
      : 600;
  tokenCacheState.token = json.access_token;
  tokenCacheState.expiresAt = Date.now() + expiresIn * 1000 - 30_000;

  return json.access_token;
}

export function buildSmeDbOAuthStart(params?: {
  redirectUri?: string;
  state?: string;
}): {
  authorizeUrl: string;
  redirectUri: string;
  state: string;
  probe: SmeDbAuthorizeProbeResult | null;
} {
  const creds = smeDbGetResolvedCredentials();
  const err = validateSmeDbClientCredentials(creds);
  if (err) throw new Error(err);

  const redirectUri = resolveRedirectUri(creds, params?.redirectUri);
  const state = params?.state?.trim() || randomOAuthState();
  const authorizeUrl = buildSmeDbAuthorizeUrl(creds.endpoints.authUrl, {
    redirectUri,
    clientId: creds.clientId,
    state,
    scope: creds.endpoints.scope,
  });

  return { authorizeUrl, redirectUri, state, probe: null };
}

import { readSmeDbEnv } from "./env-config.js";
import type { SmeDbEndpoints } from "./shared.js";

export type SmeDbResolvedCredentials = {
  clientId: string;
  clientSecret: string;
  refreshToken: string;
  environment: "sandbox" | "live";
  publicOrigin: string | null;
  endpoints: SmeDbEndpoints;
};

export function smeDbGetResolvedCredentials(): SmeDbResolvedCredentials {
  const e = readSmeDbEnv();
  return {
    clientId: e.clientId,
    clientSecret: e.clientSecret,
    refreshToken: e.refreshToken,
    environment: e.environment,
    publicOrigin: e.publicOrigin,
    endpoints: e.endpoints,
  };
}

export function validateSmeDbClientCredentials(
  creds: SmeDbResolvedCredentials
): string | null {
  if (!creds.clientId) return "SME_DB_CLIENT_ID fehlt.";
  if (!creds.clientSecret) return "SME_DB_CLIENT_SECRET fehlt.";
  return null;
}

export function validateSmeDbUserSession(
  creds: SmeDbResolvedCredentials
): string | null {
  const clientErr = validateSmeDbClientCredentials(creds);
  if (clientErr) return clientErr;
  if (!creds.refreshToken) {
    return "SME_DB_REFRESH_TOKEN fehlt — OAuth mit sme_db_oauth_start / Callback ausführen und Refresh-Token in die Env speichern.";
  }
  return null;
}

